using System;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PurifyCorruptXTimesAction", menuName = "Data/Battle/Battle Actions/Purification Actions/PurifyCorruptXTimes Action")]
public class PurifyCorruptXTimesAction : BattleAction
{
	[Header("Purify Action")]
	[SerializeField]
	[HideIf("corrupt")]
	private PurifiedLightningAction purifiedLightningAction;

	[SerializeField]
	private bool corrupt;

	[SerializeField]
	[ShowIf("corrupt")]
	private CorruptedLightningAction corruptedLightningAction;

	[SerializeField]
	private int timesAmount;

	[SerializeField]
	private bool twinSmash;

	public override void CastTargetAmount(GameObject target, int purifyCorruptAmount, GameObject source)
	{
		if (corrupt)
		{
			corruptedLightningAction.SingleTargetCastDefault(target, timesAmount, purifyCorruptAmount, source);
			return;
		}
		int num = timesAmount;
		if (twinSmash && ReferenceSingleton<CellariusOmensHandler>.Instance.RunicOarOmenAction != null)
		{
			num += ReferenceSingleton<CellariusOmensHandler>.Instance.RunicOarOmenAction(arg: true);
		}
		purifiedLightningAction.SingleTargetCastDefault(target, num, purifyCorruptAmount, source);
	}

	public Tuple<int, string> GetTimesAmount()
	{
		if (!corrupt && twinSmash)
		{
			int num = timesAmount;
			if (GameScenesUtils.IsBattleScene() && ReferenceSingleton<CellariusOmensHandler>.Instance.RunicOarOmenAction != null)
			{
				num += ReferenceSingleton<CellariusOmensHandler>.Instance.RunicOarOmenAction(arg: false);
				return Tuple.Create(num, $"{num}({timesAmount}+{num - timesAmount})");
			}
		}
		return Tuple.Create(timesAmount, "");
	}
}
